#nullable enable // autogenerated

using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Effects;
using MVZ2.GameContent.Entities;
using MVZ2.Vanilla.Enemies;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Level;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Modifiers;
using Tools;
using UnityEngine;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEnemyNames.zombieSpectre)]
    public class ZombieSpectre : AIEntityBehaviour
    {
        public ZombieSpectre(string nsp, string name) : base(nsp, name)
        {
            AddModifier(ColorModifier.Multiply(EngineEntityProps.TINT, PROP_TINT_MULTIPLIER));
            AddModifier(new BooleanModifier(VanillaEntityProps.CAN_DEACTIVE, PROP_CAN_DEACTIVE));
            AddModifier(new BooleanModifier(VanillaEntityProps.INVISIBLE, PROP_INVINCIBLE));
            AddModifier(new BooleanModifier(EngineEntityProps.INVINCIBLE, PROP_INVINCIBLE));
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            SetAppearTimer(entity, new FrameTimer(APPEAR_FRAMES));
        }
        protected override void UpdateAI(Entity enemy)
        {
            base.UpdateAI(enemy);
            if (enemy.State == STATE_APPEAR)
            {
                UpdateAppear(enemy);
            }
            var timer = GetAppearTimer(enemy);
            if (timer != null)
            {
                enemy.SetProperty(PROP_CAN_DEACTIVE, timer.Expired);
                enemy.SetProperty(PROP_INVINCIBLE, !timer.Expired);
                enemy.SetProperty(PROP_TINT_MULTIPLIER, new Color(1, 1, 1, timer.GetPassedPercentage()));
            }
        }
        private void UpdateAppear(Entity enemy)
        {
            var timer = GetAppearTimer(enemy);
            if (timer == null)
            {
                timer = new FrameTimer(APPEAR_FRAMES);
                SetAppearTimer(enemy, timer);
            }
            timer.Run();
        }
        public override void PostDeath(Entity entity, DeathInfo info)
        {
            base.PostDeath(entity, info);
            if (info.HasEffect(VanillaDamageEffects.DROWN) || info.HasEffect(VanillaDamageEffects.FALL_OFF))
                return;
            for (var i = 0; i < 2; i++)
            {
                entity.Spawn(VanillaEffectID.soulEffect, entity.GetCenter());
            }
        }
        public static FrameTimer? GetAppearTimer(Entity enemy) => enemy.GetBehaviourField<FrameTimer>(PROP_APPEAR_TIMER);
        public static void SetAppearTimer(Entity enemy, FrameTimer? value) => enemy.SetBehaviourField(PROP_APPEAR_TIMER, value);
        public static bool IsAppearing(Entity enemy) => enemy.GetProperty<bool>(PROP_INVINCIBLE);
        public static readonly VanillaEntityPropertyMeta<bool> PROP_CAN_DEACTIVE = new VanillaEntityPropertyMeta<bool>("can_deactive", true);
        public static readonly VanillaEntityPropertyMeta<bool> PROP_INVINCIBLE = new VanillaEntityPropertyMeta<bool>("invincible");
        public static readonly VanillaEntityPropertyMeta<FrameTimer> PROP_APPEAR_TIMER = new VanillaEntityPropertyMeta<FrameTimer>("appear_timer");
        public static readonly VanillaEntityPropertyMeta<Color> PROP_TINT_MULTIPLIER = new VanillaEntityPropertyMeta<Color>("tint_multiplier", Color.white);
        public const int APPEAR_FRAMES = 20;
        public const int STATE_APPEAR = VanillaEnemyStates.ZOMBIE_SPECTRE_APPEAR;
    }
}
